# If true, passing passing a different revision from the one given in the application when syncing requires the `override` privilege.
  # The current default setting up to now (`false`) requires only `sync` privilege for syncing to a different revision.
  # We highly recommend that this be set to `true`. The next major release will set the default to be `true`.
  application.sync.requireOverridePrivilegeForRevisionSync: "true"

  ### SourceHydrator commit author name (optional).
  # Configures the author name for commits created by the Source Hydrator.
  # If not specified, defaults to "Argo CD".
  commit.author.name: "Argo CD"

  ### SourceHydrator commit author email (optional).
  # Configures the author email for commits created by the Source Hydrator.
  # If not specified, defaults to "argo-cd@example.com".
  commit.author.email: "argo-cd@example.com"

  ### SourceHydrator commit message template.
  # This template iterates through the fields in the `.metadata` object,
  # and formats them based on their type (map, array, or primitive values).
  # This is the default template and targets specific metadata properties
  sourceHydrator.commitMessageTemplate: |
    {{.metadata.drySha | trunc 7}}: {{ .metadata.subject }}
    {{- if .metadata.body }}

    {{ .metadata.body }}
    {{- end }}
    {{ range $ref := .metadata.references }}
    {{- if and $ref.commit $ref.commit.author }}
    Co-authored-by: {{ $ref.commit.author }}
    {{- end }}
    {{- end }}
    {{- if .metadata.author }}
    Co-authored-by: {{ .metadata.author }}
    {{- end }}

### SourceHydrator readme message template.
  # This template defines the content of the README.md file that is automatically
  # generated during the hydration process. It can use placeholders such as
  # `.RepoURL`, `.DrySHA`, and `.Commands` to provide reproducible instructions.
  #
  # The template is dynamically loaded from a ConfigMap, which allows customizing
  # the README format depending on the environment or requirements.
  sourceHydrator.readmeMessageTemplate: |
    # Manifest Hydration

    To hydrate the manifests in this repository, run the following commands:

    ```shell
    git clone {{ .RepoURL }}
    # cd into the cloned directory
    git checkout {{ .DrySHA }}
    {{ range $command := .Commands -}}
    {{ $command }}
    {{ end -}}
    ```

    {{ if .References -}}
    ## References

    {{ range $ref := .References -}}
    {{ if $ref.Commit -}}
    * [{{ $ref.Commit.SHA | mustRegexFind "[0-9a-f]+" | trunc 7 }}]({{ $ref.Commit.RepoURL }}): {{ $ref.Commit.Subject }} ({{ $ref.Commit.Author }})
    {{ end -}}
    {{ end -}}
    {{ end -}}

